function daysUntilWarmer(temps: number[]): number[] {
  const wait = new Array<number>(temps.length).fill(0);
  const stack: number[] = []; // indices of days still waiting
  for (let i = 0; i < temps.length; i++) {
    while (stack.length && temps[i] > temps[stack[stack.length - 1]]) {
      const j = stack.pop()!;
      wait[j] = i - j;
    }
    stack.push(i);
  }
  return wait;
}

