function daysUntilWarmer(temps: number[]): number[] {
  const n = temps.length;
  const wait = new Array<number>(n).fill(0);
  let hottest = -Infinity;
  for (let i = n - 1; i >= 0; i--) {
    if (temps[i] >= hottest) {
      hottest = temps[i]; // nothing to the right is warmer
      continue;
    }
    let j = i + 1;
    while (temps[j] <= temps[i]) j += wait[j];
    wait[i] = j - i;
  }
  return wait;
}

